// Certified v4 convex hulls, measured from all wood and hardware owned by each shin.
// Source frame matches characterTransforms.along(knee, ankle).
const supportCache=new Map();
// The shin has constant planar length. Project its 3D hull into the plane of
// all possible floor normals for the current depth offset, then retain only
// its 2D hull. This is exact for every joint angle, not a sampled approximation.
export function shinFloorSupport(variant,side,scale,dz,planarLength){
  const key=[variant,side,scale,dz,planarLength].join(':');if(supportCache.has(key))return supportCache.get(key);
  const shape=SHIN_SHAPES[variant][side],length=Math.hypot(planarLength,dz);
  const projected=shape.vertices.map(vertex=>({vertex,x:vertex[0]*scale,y:vertex[1]*planarLength/shape.length-vertex[2]*dz*scale/length})).sort((a,b)=>a.x-b.x||a.y-b.y);
  const cross=(a,b,c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x),half=points=>{
    const hull=[];for(const p of points){while(hull.length>1&&cross(hull.at(-2),hull.at(-1),p)<=0)hull.pop();hull.push(p);}return hull;
  };
  const lower=half(projected),upper=half(projected.slice().reverse());lower.pop();upper.pop();
  const result={length:shape.length,vertices:[...lower,...upper].map(p=>p.vertex)};
  if(supportCache.size>=64)supportCache.delete(supportCache.keys().next().value);
  supportCache.set(key,result);return result;
}
